34	/**
35	 * Unified realtime session. `provider.engine` selects the engine:
36	 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
37	 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
38	 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
39	 * All expose the same `SessionApi` so the UI is provider-agnostic.
40	 *
41	 * Both real-engine hooks (`useConversation`, `useXaiSession`) are called
42	 * unconditionally (rules of hooks) and stay inert until their engine is
43	 * selected and started.
44	 */
45	export function useRealtimeSession({
46	  provider,
47	  persona,
48	}: {
49	  provider: Provider;
50	  persona?: Persona;
51	}): SessionApi {
52	  const engine = provider.engine;
53	  const isReal = !!engine;
54	
55	  const [callState, setCallState] = useState<CallState>(isReal ? "idle" : "listening");
56	  const [turns, setTurns] = useState<SessionTurn[]>(isReal ? [] : SCRIPT_TURNS);
57	  const [caption, setCaption] = useState<string>(
58	    isReal ? "press CALL to begin" : mockCaption("listening"),
59	  );
60	  const [muted, setMuted] = useState(false);
61	  const [elapsed, setElapsed] = useState(0);
62	
63	  const stateRef = useRef(callState);
64	  stateRef.current = callState;
65	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
66	  const clearTimers = () => {
67	    timers.current.forEach(clearTimeout);
68	    timers.current = [];
69	  };
70	
71	  // ── ElevenLabs real conversation ──────────────────────────────────────────
72	  const realPhase = useRef<"idle" | "active" | "ended">("idle");
73	  const conversation = useConversation({
74	    micMuted: muted,
75	    onMessage: (msg: { source?: string; message?: string }) => {
76	      const who = msg.source === "user" ? "user" : "agent";
77	      const text = msg.message ?? "";
78	      if (!text) return;
79	      setTurns((prev) => [...prev, { id: `r${prev.length}`, who, text }]);
80	      setCaption(text);
81	    },
82	    onError: () => {
83	      realPhase.current = "ended";
84	      setCallState("ended");
85	      setCaption("— connection error —");
86	    },
87	  });
88	
89	  const { status, mode, isSpeaking, startSession, endSession } = conversation;
90	
91	  // ── xAI Grok real conversation (direct WebSocket) ─────────────────────────
92	  const xai = useXaiSession(engine === "xai", persona);
93	
94	  // The active call state comes from whichever engine owns the session.
95	  const activeCallState: CallState = engine === "xai" ? xai.callState : callState;
96	
97	  // Derive real CallState from the conversation status/mode (ElevenLabs only).
98	  useEffect(() => {
99	    if (engine !== "elevenlabs" || realPhase.current === "idle") return;
100	    if (realPhase.current === "ended") {
101	      setCallState("ended");
102	      return;
103	    }
104	    if (status === "connecting") setCallState("connecting");
105	    else if (status === "error") setCallState("ended");
106	    else if (status === "disconnected") setCallState("ended");
107	    else if (status === "connected") {
108	      setCallState(mode === "speaking" || isSpeaking ? "speaking" : "listening");
109	      setCaption((c) => (c === "establishing session…" ? "listening…" : c));
110	    }
111	  }, [engine, status, mode, isSpeaking]);
112	
113	  // ── Mock lifecycle ──────────────────────────────────────────────────────────
114	  // First-load drift: listening → speaking after 5s (matches the prototype).
115	  useEffect(() => {
116	    if (isReal) return;
117	    if (callState !== "listening") return;
118	    const t = setTimeout(() => setCallState("speaking"), 5000);
119	    return () => clearTimeout(t);
120	    // eslint-disable-next-line react-hooks/exhaustive-deps
121	  }, [isReal]);
122	
123	  // Caption sync for the mock engine.
124	  useEffect(() => {
125	    if (isReal) return;
126	    setCaption(mockCaption(callState));
127	  }, [isReal, callState]);
128	
129	  // Elapsed ticker (all engines) — keyed off whichever engine owns the call.
130	  useEffect(() => {
131	    if (activeCallState === "idle" || activeCallState === "ended") {
132	      setElapsed(0);
133	      return;
134	    }
135	    const t = setInterval(() => setElapsed((e) => e + 1), 1000);
136	    return () => clearInterval(t);
137	  }, [activeCallState]);
138	
139	  // Push mute into the active real engine. ElevenLabs only accepts setMuted once
140	  // connected (it throws "No active conversation" before startSession()); xAI
141	  // gates its own mic send, so it's always safe.
142	  useEffect(() => {
143	    if (engine === "elevenlabs" && status === "connected") conversation.setMuted(muted);
144	    else if (engine === "xai") xai.setMuted(muted);
145	    // eslint-disable-next-line react-hooks/exhaustive-deps
146	  }, [muted, engine, status]);
147	
148	  // Reset to the active engine's initial state when the engine changes. End any
149	  // live ElevenLabs session we're navigating away from (xAI tears itself down
150	  // via its own `active` effect).
151	  useEffect(() => {
152	    clearTimers();
153	    try {
154	      if (realPhase.current === "active") endSession();
155	    } catch {
156	      // no active ElevenLabs session
157	    }
158	    realPhase.current = "idle";
159	    if (isReal) {
160	      setCallState("idle");
161	      setTurns([]);
162	      setCaption("press CALL to begin");
163	    } else {
164	      setCallState("listening");
165	      setTurns(SCRIPT_TURNS);
166	      setCaption(mockCaption("listening"));
167	    }
168	    // eslint-disable-next-line react-hooks/exhaustive-deps
169	  }, [engine]);
170	
171	  useEffect(() => () => clearTimers(), []);
172	
173	  // ── Controls ────────────────────────────────────────────────────────────────
174	  const start = useCallback(() => {
175	    if (engine === "xai") {
176	      xai.start();
177	      return;
178	    }
179	    if (engine === "elevenlabs") {
180	      if (callState === "idle" || callState === "ended") {
181	        const agentId = process.env.NEXT_PUBLIC_ELEVENLABS_AGENT_ID;
182	        if (!agentId) {
183	          setCaption("— set NEXT_PUBLIC_ELEVENLABS_AGENT_ID —");
184	          return;
185	        }
186	        realPhase.current = "active";
187	        setTurns([]);
188	        setCallState("connecting");
189	        setCaption("establishing session…");
190	        startSession({ agentId, connectionType: "webrtc" } as Parameters<typeof startSession>[0]);
191	      } else {
192	        realPhase.current = "ended";
193	        endSession();
194	        setCallState("ended");
195	      }
196	      return;
197	    }
198	    // Mock
199	    clearTimers();
200	    if (callState === "idle" || callState === "ended") {
201	      setTurns(SCRIPT_TURNS);
202	      setCallState("connecting");
203	      timers.current.push(setTimeout(() => setCallState("listening"), 1400));
204	      timers.current.push(setTimeout(() => setCallState("speaking"), 3600));
205	    } else {
206	      setCallState("ended");
207	    }
208	  }, [engine, xai, callState, startSession, endSession]);
209	
210	  const hangup = useCallback(() => {
211	    if (engine === "xai") {
212	      xai.stop();
213	      return;
214	    }
215	    if (engine === "elevenlabs") {
216	      realPhase.current = "ended";
217	      endSession();
218	    } else {
219	      clearTimers();
220	    }
221	    setCallState("ended");
222	  }, [engine, xai, endSession]);
223	
224	  const interrupt = useCallback(() => {
225	    if (engine === "xai") {
226	      xai.interrupt();
227	      return;
228	    }
229	    if (stateRef.current !== "speaking") return;
230	    if (engine === "elevenlabs") {
231	      conversation.sendUserActivity();
232	      setCallState("interrupted");
233	      return;
234	    }
235	    clearTimers();
236	    setCallState("interrupted");
237	    timers.current.push(setTimeout(() => setCallState("listening"), 900));
238	  }, [engine, xai, conversation]);
239	
240	  const toggleMute = useCallback(() => setMuted((m) => !m), []);
241	
242	  // ── Volumes for the orb ───────────────────────────────────────────────────
243	  const getInputVolume = useCallback(() => {
244	    if (engine === "elevenlabs") {
245	      // Throws before startSession(); fall back to silence until connected.
246	      try {
247	        return conversation.getInputVolume();
248	      } catch {
249	        return 0;
250	      }
251	    }
252	    const s = stateRef.current;
253	    if (s === "listening" || s === "interrupted") {
254	      return 0.25 + 0.4 * Math.abs(Math.sin(performance.now() / 180));
255	    }
256	    return 0.04;
257	  }, [engine, conversation]);
258	
259	  const getOutputVolume = useCallback(() => {
260	    if (engine === "elevenlabs") {
261	      try {
262	        return conversation.getOutputVolume();
263	      } catch {
264	        return 0;
265	      }
266	    }
267	    const s = stateRef.current;
268	    if (s === "speaking") {
269	      return 0.4 + 0.45 * Math.abs(Math.sin(performance.now() / 140));
270	    }
271	    return 0.04;
272	  }, [engine, conversation]);
273	
274	  const isXai = engine === "xai";
275	
276	  return useMemo<SessionApi>(
277	    () => ({
278	      callState: activeCallState,
279	      turns: isXai ? xai.turns : turns,
280	      caption: isXai ? xai.caption : caption,
281	      muted,
282	      elapsed,
283	      isReal,
284	      toggleMute,
285	      start,
286	      hangup,
287	      interrupt,
288	      getInputVolume: isXai ? xai.getInputVolume : getInputVolume,
289	      getOutputVolume: isXai ? xai.getOutputVolume : getOutputVolume,
290	    }),
291	    [
292	      activeCallState,
293	      isXai,
294	      xai,
295	      turns,
296	      caption,
297	      muted,
298	      elapsed,
299	      isReal,
300	      toggleMute,
301	      start,
302	      hangup,
303	      interrupt,
304	      getInputVolume,
305	      getOutputVolume,
306	    ],
307	  );
308	}
