1	// Mints a short-lived xAI realtime client-secret (ephemeral token) server-side
2	// so the browser can open a WebSocket to xAI WITHOUT ever seeing XAI_API_KEY.
3	//
4	// Flow: client POSTs here → we call xAI with the secret key → return the
5	// ephemeral token JSON. The browser then connects with
6	//   new WebSocket(".../v1/realtime?model=…", ["xai-client-secret." + token]).
7	//
8	// Dev only: XAI_API_KEY is provided via fnox (`fnox exec -- bun run dev`).
9	
10	export const runtime = "nodejs";
11	// Never cache a freshly-minted secret.
12	export const dynamic = "force-dynamic";
13	
14	const CLIENT_SECRETS_URL = "https://api.x.ai/v1/realtime/client_secrets";
15	const TOKEN_TTL_SECONDS = 300;
16	
17	export async function POST(): Promise<Response> {
18	  const apiKey = process.env.XAI_API_KEY;
19	  if (!apiKey) {
20	    // Do not echo any key material; just say it's unset.
21	    return Response.json(
22	      { error: "XAI_API_KEY is not set on the server (provide it via fnox)." },
23	      { status: 500 },
24	    );
25	  }
26	
27	  let upstream: Response;
28	  try {
29	    upstream = await fetch(CLIENT_SECRETS_URL, {
30	      method: "POST",
31	      headers: {
32	        Authorization: `Bearer ${apiKey}`,
33	        "Content-Type": "application/json",
34	      },
35	      body: JSON.stringify({ expires_after: { seconds: TOKEN_TTL_SECONDS } }),
36	    });
37	  } catch (err) {
38	    return Response.json(
39	      { error: `Failed to reach xAI: ${err instanceof Error ? err.message : "network error"}` },
40	      { status: 502 },
41	    );
42	  }
43	
44	  const text = await upstream.text();
45	  if (!upstream.ok) {
46	    // Surface xAI's status + body (it doesn't contain our key) for debugging.
47	    return Response.json(
48	      { error: "xAI client_secrets request failed", status: upstream.status, detail: text },
49	      { status: 502 },
50	    );
51	  }
52	
53	  // Pass the token JSON straight through; the client extracts the value defensively.
54	  return new Response(text, {
55	    status: 200,
56	    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
57	  });
58	}
