1	"use client";
2	
3	// Real xAI Grok voice engine over a DIRECT browser→xAI WebSocket.
4	//
5	// Architecture (no relay server): mint an ephemeral client-secret at
6	// /api/xai/token, then open `wss://api.x.ai/v1/realtime` carrying the token in
7	// the subprotocol (browsers can't set WS headers). We own the whole audio
8	// pipeline: mic → PCM16 → `input_audio_buffer.append`; inbound
9	// `response.output_audio.delta` → PCM16 → AudioBuffer playback. Barge-in is
10	// server-VAD driven (`input_audio_buffer.speech_started` → stop playback).
11	//
12	// Exposes a surface deliberately parallel to @elevenlabs/react's useConversation
13	// so useRealtimeSession can dispatch to either engine uniformly. Must be called
14	// unconditionally (rules of hooks); it stays inert until start().
15	
16	import { useCallback, useEffect, useRef, useState } from "react";
17	import type { Persona } from "@/lib/data";
18	import type { CallState, SessionTurn } from "./types";
19	import { resolveXaiAgent } from "./xai-agent";
20	import {
21	  base64Pcm16ToFloat32,
22	  calculateRms,
23	  EarlyAudioBuffer,
24	  float32ToPcm16Base64,
25	  PlaybackQueue,
26	} from "./xai-audio";
27	
28	const REALTIME_BASE = "wss://api.x.ai/v1/realtime";
29	const CHUNK_MS = 100;
30	const VOL_GAIN = 3.5;
31	
32	export interface XaiSession {
33	  callState: CallState;
34	  turns: SessionTurn[];
35	  caption: string;
36	  start: () => void;
37	  stop: () => void;
38	  interrupt: () => void;
39	  setMuted: (muted: boolean) => void;
40	  getInputVolume: () => number;
41	  getOutputVolume: () => number;
42	}
43	
44	type XaiEvent = {
45	  type: string;
46	  delta?: string;
47	  transcript?: string;
48	  error?: { type?: string; code?: string; message?: string };
49	  item?: { role?: string; content?: Array<{ type?: string; transcript?: string; text?: string }> };
50	};
51	
52	function extractToken(data: unknown): string | null {
53	  if (typeof data !== "object" || data === null) return null;
54	  const d = data as Record<string, unknown>;
55	  if (typeof d.value === "string") return d.value;
56	  if (typeof d.token === "string") return d.token;
57	  if (typeof d.secret === "string") return d.secret;
58	  const cs = d.client_secret;
59	  if (typeof cs === "string") return cs;
60	  if (cs && typeof cs === "object" && typeof (cs as Record<string, unknown>).value === "string") {
61	    return (cs as Record<string, unknown>).value as string;
62	  }
63	  return null;
64	}
