236	    // Kick capture off now — do not await it, and do not wait for the WS.
237	    void startCapture();
238	
239	    void (async () => {
240	      // 2) Mint the ephemeral client-secret server-side (in parallel with capture).
241	      let token: string | null = null;
242	      try {
243	        const res = await fetch("/api/xai/token", { method: "POST" });
244	        const data = await res.json();
245	        if (!res.ok) {
246	          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
247	          return;
248	        }
249	        token = extractToken(data);
250	      } catch {
251	        fail("— could not reach token endpoint —");
252	        return;
253	      }
254	      if (!token) {
255	        fail("— no xAI token returned —");
256	        return;
257	      }
258	      if (endedRef.current) return; // hung up (or mic denied) during fetch
259	
260	      // ── transcript helpers ──────────────────────────────────────────────
261	      const pushAgentDelta = (delta: string) => {
262	        agentBufRef.current += delta;
263	        const text = agentBufRef.current;
264	        setCaption(text);
265	        setTurns((prev) => {
266	          const id = agentTurnIdRef.current;
267	          if (id) return prev.map((t) => (t.id === id ? { ...t, text } : t));
268	          const newId = `x${turnSeqRef.current++}`;
269	          agentTurnIdRef.current = newId;
270	          return [...prev, { id: newId, who: "agent", text, live: true }];
271	        });
272	      };
273	      const finalizeAgent = () => {
274	        const id = agentTurnIdRef.current;
275	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
276	        agentTurnIdRef.current = null;
277	        agentBufRef.current = "";
278	      };
279	      const pushUser = (text: string) => {
280	        if (!text) return;
281	        setTurns((prev) => [...prev, { id: `x${turnSeqRef.current++}`, who: "user", text }]);
282	        setCaption(text);
283	      };
284	
285	      // 3) Resolve the active persona's agent config, then open the WS
286	      //    (token rides the subprotocol since browsers can't set WS headers).
287	      const agent = resolveXaiAgent(personaRef.current?.id);
288	      const ws = new WebSocket(`${REALTIME_BASE}?model=${encodeURIComponent(agent.model)}`, [
289	        `xai-client-secret.${token}`,
290	      ]);
291	      wsRef.current = ws;
292	
293	      const configure = () => {
294	        if (configuredRef.current) return;
295	        configuredRef.current = true;
296	        send({
297	          type: "session.update",
298	          session: {
299	            instructions: agent.instructions,
300	            voice: agent.voice,
301	            audio: {
302	              input: { format: { type: "audio/pcm", rate } },
303	              output: { format: { type: "audio/pcm", rate } },
304	            },
305	            turn_detection: agent.turnDetection,
306	            tools: agent.tools,
307	          },
308	        });
309	      };
310	
311	      ws.onmessage = (event) => {
312	        if (endedRef.current) return; // ignore late events after teardown
313	        let msg: XaiEvent;
314	        try {
315	          msg = JSON.parse(typeof event.data === "string" ? event.data : "") as XaiEvent;
316	        } catch {
317	          return;
318	        }
319	        switch (msg.type) {
320	          case "conversation.created":
321	          case "session.created":
322	            configure();
323	            break;
324	          case "session.updated": {
325	            // Session is configured: switch capture to live streaming and flush
326	            // any audio the user already spoke during connect — in order, BEFORE
327	            // the greeting bootstrap — so their opening words reach the model.
328	            streamingRef.current = true;
329	            const buffered = earlyBufRef.current?.drain() ?? [];
330	            for (const audio of buffered) {
331	              send({ type: "input_audio_buffer.append", audio });
332	            }
333	            setCallState("listening");
334	            setCaption("listening…");
335	            // Prompt an opening line so the agent speaks first.
336	            send({
337	              type: "conversation.item.create",
338	              item: {
339	                type: "message",
340	                role: "user",
341	                content: [{ type: "input_text", text: agent.firstMessage }],
342	              },
343	            });
344	            send({ type: "response.create" });
345	            break;
346	          }
347	          case "response.output_audio.delta":
348	            if (msg.delta) {
349	              playbackRef.current?.enqueue(base64Pcm16ToFloat32(msg.delta));
350	              if (stateRef.current !== "interrupted") setCallState("speaking");
351	            }
352	            break;
353	          case "response.output_audio_transcript.delta":
354	            if (msg.delta) pushAgentDelta(msg.delta);
355	            break;
356	          case "response.done":
357	            finalizeAgent();
358	            if (stateRef.current === "speaking") setCallState("listening");
359	            break;
360	          case "input_audio_buffer.speech_started":
361	            // Server VAD detected the user — barge-in: stop the agent audio.
362	            playbackRef.current?.stop();
363	            finalizeAgent();
364	            setCallState("interrupted");
365	            if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
366	            interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
367	            break;
368	          case "input_audio_buffer.committed":
369	          case "input_audio_buffer.speech_stopped":
370	            if (stateRef.current === "interrupted") setCallState("listening");
371	            break;
372	          case "conversation.item.added":
373	          case "conversation.item.created": {
374	            const item = msg.item;
375	            if (item?.role === "user") {
376	              const t = item.content?.find((c) => c.transcript || c.text);
377	              if (t) pushUser((t.transcript ?? t.text ?? "").trim());
378	            }
379	            break;
380	          }
381	          case "error":
382	            // Surface but don't kill — a fatal error will also close the socket.
383	            setCaption(`— ${msg.error?.message ?? "xAI error"} —`);
384	            break;
385	          default:
386	            break;
387	        }
388	      };
389	
390	      ws.onerror = () => {
391	        if (endedRef.current) return;
392	        endedRef.current = true;
393	        teardown();
394	        setCallState("ended");
395	        setCaption("— connection error —");
396	      };
397	
398	      ws.onclose = () => {
399	        if (endedRef.current) return;
400	        endedRef.current = true;
401	        teardown();
402	        setCallState("ended");
403	        setCaption("— call ended —");
404	      };
405	    })();
406	  }, [send, teardown]);
407	
408	  const stop = useCallback(() => {
409	    endedRef.current = true;
410	    teardown();
411	    setCallState("ended");
412	    setCaption("— call ended —");
413	  }, [teardown]);
414	
415	  const interrupt = useCallback(() => {
416	    if (stateRef.current !== "speaking") return;
417	    playbackRef.current?.stop();
418	    setCallState("interrupted");
419	    if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
420	    interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
421	  }, []);
422	
423	  const setMuted = useCallback((muted: boolean) => {
424	    mutedRef.current = muted;
425	    if (muted) inputRmsRef.current = 0;
426	  }, []);
427	
428	  const getInputVolume = useCallback(() => Math.min(1, inputRmsRef.current * VOL_GAIN), []);
429	  const getOutputVolume = useCallback(
430	    () => Math.min(1, (playbackRef.current?.level ?? 0) * VOL_GAIN),
431	    [],
432	  );
433	
434	  // Hang up + reset if the provider is switched away from xAI mid-session.
435	  useEffect(() => {
436	    if (active) return;
437	    if (stateRef.current !== "idle") {
438	      endedRef.current = true;
439	      teardown();
440	      setCallState("idle");
441	      setTurns([]);
442	      setCaption("press CALL to begin");
443	    }
444	  }, [active, teardown]);
445	
446	  // Cleanup on unmount.
447	  useEffect(() => () => teardown(), [teardown]);
448	
449	  return {
450	    callState,
451	    turns,
452	    caption,
453	    start,
454	    stop,
455	    interrupt,
456	    setMuted,
457	    getInputVolume,
458	    getOutputVolume,
459	  };
460	}
