// Mints a short-lived OpenAI realtime ephemeral key (client secret) server-side
// so the browser can open a WebRTC session WITHOUT ever seeing OPENAI_API_KEY.
//
// Flow: client POSTs here → we call OpenAI with the secret key → return the
// ephemeral key JSON. The browser then negotiates WebRTC directly with OpenAI:
//   POST https://api.openai.com/v1/realtime/calls
//     Authorization: Bearer <ephemeral key>, Content-Type: application/sdp
// Full per-persona config is applied client-side via `session.update`, so the
// mint body stays minimal here.
//
// Dev only: OPENAI_API_KEY is provided via fnox (`fnox exec -- bun run dev`).

export const runtime = "nodejs";
// Never cache a freshly-minted secret.
export const dynamic = "force-dynamic";

const CLIENT_SECRETS_URL = "https://api.openai.com/v1/realtime/client_secrets";
const MODEL = "gpt-realtime-2";

export async function POST(): Promise<Response> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    // Do not echo any key material; just say it's unset.
    return Response.json(
      { error: "OPENAI_API_KEY is not set on the server (provide it via fnox)." },
      { status: 500 },
    );
  }

  let upstream: Response;
  try {
    upstream = await fetch(CLIENT_SECRETS_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ session: { type: "realtime", model: MODEL } }),
    });
  } catch (err) {
    return Response.json(
      { error: `Failed to reach OpenAI: ${err instanceof Error ? err.message : "network error"}` },
      { status: 502 },
    );
  }

  const text = await upstream.text();
  if (!upstream.ok) {
    // Surface OpenAI's status + body (it doesn't contain our key) for debugging.
    return Response.json(
      { error: "OpenAI client_secrets request failed", status: upstream.status, detail: text },
      { status: 502 },
    );
  }

  // Pass the key JSON straight through; the client extracts the value defensively.
  return new Response(text, {
    status: 200,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
  });
}

// OpenAI realtime agent configuration — the source of truth for what each
// persona sounds and behaves like on the real `gpt-realtime-2` engine.
//
// Ported from `xai-agent.ts` (same authoring model: shared transport in BASE,
// per-persona overrides for voice + prompt + greeting) and adapted to OpenAI's
// Realtime 2.0 surface:
//   - OpenAI voices (marin/cedar are the quality picks) instead of xAI's five.
//   - `reasoningEffort` (session.reasoning.effort) — default "low" per OpenAI's
//     prompting guide for production voice agents.
//   - input transcription via `gpt-realtime-whisper` (shared in BASE).
//   - per-persona `instructions` lightly structured toward OpenAI's 2.0 labeled
//     skeleton (Role, Personality & Tone, Pacing, Unclear Audio, Variety). This
//     is a customization surface, not an exhaustive implementation of the guide.
//
// `resolveOpenaiAgent(personaId)` merges a persona over BASE. Only the secret
// OPENAI_API_KEY stays outside (in fnox); everything declarative lives here.

export type OpenaiVoice =
  | "marin"
  | "cedar"
  | "alloy"
  | "ash"
  | "ballad"
  | "coral"
  | "echo"
  | "sage"
  | "shimmer"
  | "verse";

/** session.reasoning.effort — lowest level that still does the job (default low). */
export type ReasoningEffort = "minimal" | "low" | "medium" | "high" | "xhigh";

/** gpt-realtime-whisper latency/accuracy knob for input transcription. */
export type TranscriptionDelay = "minimal" | "low" | "medium" | "high" | "xhigh";

export interface OpenaiAgentConfig {
  /** Realtime model for the session + token mint. */
  model: string;
  /** One of OpenAI's built-in voices. Locked after the first audio output. */
  voice: OpenaiVoice;
  /** System prompt sent in `session.update` → `session.instructions`. */
  instructions: string;
  /** Prompt that elicits the agent's opening line (sent as a user item + response.create). */
  firstMessage: string;
  /** Reasoning effort sent as `session.reasoning.effort`. */
  reasoningEffort: ReasoningEffort;
  /** Input-audio transcription so the UI can show the user's words. */
  transcription: {
    /** Streaming transcription model — `gpt-realtime-whisper` for realtime. */
    model: string;
    /** Optional language hint such as "en". */
    language?: string;
    /** Latency/accuracy tradeoff for gpt-realtime-whisper. */
    delay?: TranscriptionDelay;
  };
  /** Tools enabled for the session. Empty by default. */
  tools: Array<{ type: string }>;
  /**
   * Turn-taking strategy. Server VAD with optional tuning — passed straight
   * through to `session.audio.input.turn_detection`. `type` is widened so a
   * future `semantic_vad` config is possible without a type change.
   */
  turnDetection: {
    type: "server_vad" | "semantic_vad";
    /** Sensitivity 0.0–1.0; higher needs louder speech to trigger. */
    threshold?: number;
    /** How long the user must stay silent before the server ends their turn. */
    silence_duration_ms?: number;
    /** Audio kept before detected speech start, so first words aren't clipped. */
    prefix_padding_ms?: number;
  };
}

// VAD presets matched to persona pacing. Snappy = quick turn-ends for fast,
// efficient personas; relaxed/patient = longer silence tolerance so measured,
// atmospheric voices aren't cut off mid-thought, with extra prefix padding to
// protect their (often soft) opening words. Numbers are tuning starting points.
const VAD_SNAPPY: OpenaiAgentConfig["turnDetection"] = {
  type: "server_vad",
  threshold: 0.6,
  silence_duration_ms: 480,
  prefix_padding_ms: 300,
};
const VAD_RELAXED: OpenaiAgentConfig["turnDetection"] = {
  type: "server_vad",
  threshold: 0.5,
  silence_duration_ms: 900,
  prefix_padding_ms: 400,
};
const VAD_PATIENT: OpenaiAgentConfig["turnDetection"] = {
  type: "server_vad",
  threshold: 0.4,
  silence_duration_ms: 1200,
  prefix_padding_ms: 500,
};

// Spoken-audio guardrails shared by every persona, plus OpenAI-recommended
// Unclear Audio + Variety rules. Each persona supplies the Role/Personality block.
const SHARED = `You are a voice agent inside Tsubaki, a realtime voice interface.
You are speaking to the user live over audio, so keep every reply short, natural, and conversational.
Never use markdown, bullet lists, headings, code blocks, or emoji — your words are spoken aloud.
If you don't know something, say so briefly.

# Unclear Audio
- Only respond to clear audio or text.
- If the user's audio is unclear, noisy, partial, or silent, ask for clarification with a short phrase like "Sorry, could you repeat that?"
- Do not guess what the user meant from unclear audio, and don't repeat the same clarification twice.

# Variety
- Vary your wording so you don't sound robotic; don't repeat the same sentence twice.`;

// Transport settings every persona shares; personas override the rest.
const BASE: Pick<
  OpenaiAgentConfig,
  "model" | "reasoningEffort" | "transcription" | "tools" | "turnDetection"
> = {
  model: "gpt-realtime-2",
  // "low" is OpenAI's recommended default for production voice agents.
  reasoningEffort: "low",
  transcription: { model: "gpt-realtime-whisper", language: "en", delay: "low" },
  tools: [],
  // Global fallback for any persona that doesn't override turnDetection.
  turnDetection: VAD_RELAXED,
};

// Per-persona personality. Keyed by `Persona.id` from lib/data.ts. Each maps to
// an OpenAI voice (nearest match to the persona's timbre) plus a hand-authored
// prompt + opening line. Edit these freely — this is the "prompt document".
type PersonaAgent = Pick<OpenaiAgentConfig, "voice" | "instructions" | "firstMessage"> & {
  /** Optional per-persona VAD override; falls back to BASE.turnDetection. */
  turnDetection?: OpenaiAgentConfig["turnDetection"];
  /** Optional per-persona reasoning override; falls back to BASE.reasoningEffort. */
  reasoningEffort?: ReasoningEffort;
};

const PERSONA_AGENTS: Record<string, PersonaAgent> = {
  // Warm, calm, measured contralto — onboarding & long-form support.
  aria: {
    voice: "marin",
    // Patient onboarding voice — tolerate the pauses of someone thinking aloud.
    turnDetection: VAD_RELAXED,
    firstMessage:
      "Greet me warmly in one short sentence as Aria, then ask what I'd like help with.",
    instructions: `${SHARED}

# Role
You are Aria: a warm, calm, measured guide tuned for onboarding and long, supportive conversations.

# Personality & Tone
Reassure before you instruct. Be patient and gentle; never rush the user.

# Pacing
Speak slowly and patiently, with low-tempo phrasing and gentle pauses. If the user seems lost, slow down further and check in.`,
  },
  // Deep, dry, laconic British bass — precise with numbers and names.
  onyx: {
    voice: "cedar",
    // Unhurried, deliberate delivery — don't clip him between weighed words.
    turnDetection: VAD_RELAXED,
    firstMessage: "Greet me in one terse sentence as Onyx — dry and unhurried.",
    instructions: `${SHARED}

# Role
You are Onyx: a gravelly, authoritative British baritone.

# Personality & Tone
You are laconic — say the most with the fewest words. Be dry, never bubbly. Prefer a single well-chosen sentence over three.

# Pacing
Read numbers, dates, and proper nouns precisely and deliberately, as if for broadcast.`,
  },
  // Clear, neutral, fast non-binary alto — the professional default.
  sage: {
    voice: "sage",
    // Professional default — fast, snappy turn-ends to feel responsive.
    turnDetection: VAD_SNAPPY,
    firstMessage: "Greet me in one crisp, neutral sentence as Sage and ask how you can help.",
    instructions: `${SHARED}

# Role
You are Sage: the professional default — clear, neutral, and efficient.

# Personality & Tone
No performed emotion, no filler. Answer directly and move on. Optimize for accuracy and brevity over warmth.

# Pacing
Even pacing with minimal affect.`,
  },
  // Bright, upbeat presenter — pitches, demos, walkthroughs.
  nova: {
    voice: "coral",
    // High-energy presenter — keep momentum with quick turn-taking.
    turnDetection: VAD_SNAPPY,
    firstMessage: "Open with an upbeat one-line hello as Nova and invite me to dive in.",
    instructions: `${SHARED}

# Role
You are Nova: a bright, high-energy presenter at your best demoing, pitching, and walking people through things step by step.

# Personality & Tone
Upbeat and enthusiastic without being exhausting. Celebrate small wins, but stay concise.

# Pacing
Keep momentum and energy up while staying easy to follow.`,
  },
  // Soft, intimate, close-mic.
  echo: {
    voice: "echo",
    // Soft, close-mic — low threshold + generous padding so quiet words register.
    turnDetection: VAD_RELAXED,
    firstMessage: "Greet me softly and intimately in one short line as Echo.",
    instructions: `${SHARED}

# Role
You are Echo: a soft, intimate voice speaking next to the listener's ear.

# Personality & Tone
Favor quiet reassurance and short, calm sentences. Never raise your energy abruptly.

# Pacing
Keep your voice low and close, unhurried and gentle.`,
  },
  // Mystery-novel narrator — atmospheric, deliberate, an ear for the telling detail.
  cipher: {
    voice: "ballad",
    // Atmospheric narrator — the longest silence tolerance, for deliberate pauses.
    turnDetection: VAD_PATIENT,
    firstMessage:
      "Open like the first sentence of a mystery novel — a single evocative line that hints something is about to happen — then ask what brought me here.",
    instructions: `${SHARED}

# Role
You are Cipher: a mystery-novel narrator.

# Personality & Tone
Speak as if reading aloud from the opening of a noir thriller. Favor concrete imagery and short sentences that breathe; never purple, never melodramatic. You may drop the occasional aside to the listener, but keep it brief — this is still a real conversation, not a monologue.

# Pacing
Measured pacing, with deliberate pauses for atmosphere.`,
  },
};

// Fallback when no persona is selected (or an unknown id).
const DEFAULT_PERSONA_AGENT: PersonaAgent = {
  voice: "marin",
  firstMessage: "Greet me briefly and ask how you can help.",
  instructions: `${SHARED}

# Role
You are a warm, engaging, empathetic realtime voice assistant.`,
};

/** Merge the selected persona's personality over the shared BASE transport config. */
export function resolveOpenaiAgent(personaId?: string): OpenaiAgentConfig {
  const persona = (personaId && PERSONA_AGENTS[personaId]) || DEFAULT_PERSONA_AGENT;
  return { ...BASE, ...persona };
}

"use client";

// Real OpenAI `gpt-realtime-2` voice engine over a browser WebRTC peer connection.
//
// Architecture (no relay server): mint an ephemeral key at /api/openai/token,
// then negotiate WebRTC directly with OpenAI — POST the local SDP offer to
// https://api.openai.com/v1/realtime/calls (Authorization: Bearer <ephemeral>)
// and apply the answer. WebRTC handles ALL audio: the mic track is sent on the
// peer connection and the model's audio arrives on a remote track played by a
// hidden <audio> element. Barge-in truncation is handled server-side. Only
// session control + transcripts ride the `oai-events` data channel.
//
// Surface is deliberately identical to useXaiSession so useRealtimeSession can
// dispatch to either uniformly. Must be called unconditionally (rules of hooks);
// it stays inert until start().

import { useCallback, useEffect, useRef, useState } from "react";
import type { Persona } from "@/lib/data";
import type { CallState, SessionTurn } from "./types";
import { resolveOpenaiAgent } from "./openai-agent";

const CALLS_URL = "https://api.openai.com/v1/realtime/calls";
const VOL_GAIN = 3.5;

export interface OpenaiSession {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  start: () => void;
  stop: () => void;
  interrupt: () => void;
  setMuted: (muted: boolean) => void;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

type OpenaiEvent = {
  type: string;
  delta?: string;
  transcript?: string;
  item_id?: string;
  error?: { type?: string; code?: string; message?: string };
};

function extractToken(data: unknown): string | null {
  if (typeof data !== "object" || data === null) return null;
  const d = data as Record<string, unknown>;
  if (typeof d.value === "string") return d.value;
  if (typeof d.client_secret === "string") return d.client_secret;
  const cs = d.client_secret;
  if (cs && typeof cs === "object" && typeof (cs as Record<string, unknown>).value === "string") {
    return (cs as Record<string, unknown>).value as string;
  }
  return null;
}

/** RMS of an analyser's current time-domain frame, scaled to a 0..1 orb level. */
function analyserLevel(analyser: AnalyserNode | null, buf: Float32Array | null): number {
  if (!analyser || !buf) return 0;
  analyser.getFloatTimeDomainData(buf);
  let sum = 0;
  for (let i = 0; i < buf.length; i++) sum += buf[i] * buf[i];
  return Math.min(1, Math.sqrt(sum / buf.length) * VOL_GAIN);
}

export function useOpenaiSession(active: boolean, persona?: Persona): OpenaiSession {
  const [callState, setCallState] = useState<CallState>("idle");
  const [turns, setTurns] = useState<SessionTurn[]>([]);
  const [caption, setCaption] = useState("press CALL to begin");

  const pcRef = useRef<RTCPeerConnection | null>(null);
  const dcRef = useRef<RTCDataChannel | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioElRef = useRef<HTMLAudioElement | null>(null);

  // Web Audio analysers for orb levels (WebRTC keeps the audio bytes itself).
  const ctxRef = useRef<AudioContext | null>(null);
  const inAnalyserRef = useRef<AnalyserNode | null>(null);
  const outAnalyserRef = useRef<AnalyserNode | null>(null);
  const inBufRef = useRef<Float32Array | null>(null);
  const outBufRef = useRef<Float32Array | null>(null);

  const mutedRef = useRef(false);
  const endedRef = useRef(false);
  const configuredRef = useRef(false);
  const greetedRef = useRef(false);

  const turnSeqRef = useRef(0);
  const agentTurnIdRef = useRef<string | null>(null);
  const agentBufRef = useRef("");
  const userTurnIdRef = useRef<string | null>(null);
  const userBufRef = useRef("");
  const interruptTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const stateRef = useRef<CallState>("idle");
  stateRef.current = callState;
  const personaRef = useRef(persona);
  personaRef.current = persona;

  const teardown = useCallback(() => {
    if (interruptTimerRef.current) {
      clearTimeout(interruptTimerRef.current);
      interruptTimerRef.current = null;
    }
    if (dcRef.current) {
      try {
        dcRef.current.close();
      } catch {
        // already closing
      }
      dcRef.current = null;
    }
    if (pcRef.current) {
      try {
        pcRef.current.close();
      } catch {
        // already closing
      }
      pcRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    if (audioElRef.current) {
      audioElRef.current.srcObject = null;
      audioElRef.current = null;
    }
    if (ctxRef.current) {
      void ctxRef.current.close();
      ctxRef.current = null;
    }
    inAnalyserRef.current = null;
    outAnalyserRef.current = null;
    inBufRef.current = null;
    outBufRef.current = null;
    configuredRef.current = false;
    greetedRef.current = false;
    agentTurnIdRef.current = null;
    agentBufRef.current = "";
    userTurnIdRef.current = null;
    userBufRef.current = "";
  }, []);

  const send = useCallback((obj: unknown) => {
    const dc = dcRef.current;
    if (dc && dc.readyState === "open") dc.send(JSON.stringify(obj));
  }, []);

  const start = useCallback(() => {
    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
    endedRef.current = false;
    configuredRef.current = false;
    greetedRef.current = false;
    setTurns([]);
    setCallState("connecting");
    setCaption("establishing session…");

    const fail = (msg: string) => {
      endedRef.current = true;
      teardown();
      setCallState("ended");
      setCaption(msg);
    };

    // ── transcript helpers ──────────────────────────────────────────────
    const pushAgentDelta = (delta: string) => {
      agentBufRef.current += delta;
      const text = agentBufRef.current;
      setCaption(text);
      setTurns((prev) => {
        const id = agentTurnIdRef.current;
        if (id) return prev.map((t) => (t.id === id ? { ...t, text } : t));
        const newId = `o${turnSeqRef.current++}`;
        agentTurnIdRef.current = newId;
        return [...prev, { id: newId, who: "agent", text, live: true }];
      });
    };
    const finalizeAgent = () => {
      const id = agentTurnIdRef.current;
      if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
      agentTurnIdRef.current = null;
      agentBufRef.current = "";
    };
    const pushUserDelta = (delta: string) => {
      userBufRef.current += delta;
      const text = userBufRef.current;
      setCaption(text);
      setTurns((prev) => {
        const id = userTurnIdRef.current;
        if (id) return prev.map((t) => (t.id === id ? { ...t, text } : t));
        const newId = `o${turnSeqRef.current++}`;
        userTurnIdRef.current = newId;
        return [...prev, { id: newId, who: "user", text, live: true }];
      });
    };
    const finalizeUser = (transcript: string) => {
      const text = transcript.trim();
      const id = userTurnIdRef.current;
      if (id) {
        setTurns((prev) =>
          prev.map((t) => (t.id === id ? { ...t, text: text || t.text, live: false } : t)),
        );
      } else if (text) {
        setTurns((prev) => [...prev, { id: `o${turnSeqRef.current++}`, who: "user", text }]);
      }
      if (text) setCaption(text);
      userTurnIdRef.current = null;
      userBufRef.current = "";
    };

    void (async () => {
      const agent = resolveOpenaiAgent(personaRef.current?.id);

      // 1) Mic capture (also feeds the input analyser for the orb).
      let stream: MediaStream;
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          audio: {
            channelCount: 1,
            echoCancellation: true,
            noiseSuppression: true,
            autoGainControl: true,
          },
        });
      } catch {
        fail("— microphone permission denied —");
        return;
      }
      if (endedRef.current) {
        stream.getTracks().forEach((t) => t.stop());
        return;
      }
      streamRef.current = stream;
      if (mutedRef.current) stream.getAudioTracks().forEach((t) => (t.enabled = false));

      // 2) Analysers — input from the mic, output from the model's remote track.
      const ctx = new AudioContext();
      ctxRef.current = ctx;
      const inAnalyser = ctx.createAnalyser();
      inAnalyser.fftSize = 1024;
      ctx.createMediaStreamSource(stream).connect(inAnalyser);
      inAnalyserRef.current = inAnalyser;
      inBufRef.current = new Float32Array(inAnalyser.fftSize);

      // 3) Peer connection + remote audio playback.
      const pc = new RTCPeerConnection();
      pcRef.current = pc;
      const audioEl = document.createElement("audio");
      audioEl.autoplay = true;
      audioElRef.current = audioEl;
      pc.ontrack = (e) => {
        const [remote] = e.streams;
        if (!remote) return;
        audioEl.srcObject = remote;
        // Tap the remote stream for the output orb level (analyser only; the
        // <audio> element does the actual playback, so don't reach destination).
        try {
          const outAnalyser = ctx.createAnalyser();
          outAnalyser.fftSize = 1024;
          ctx.createMediaStreamSource(remote).connect(outAnalyser);
          outAnalyserRef.current = outAnalyser;
          outBufRef.current = new Float32Array(outAnalyser.fftSize);
        } catch {
          // analyser is best-effort; playback still works without it
        }
      };
      stream.getTracks().forEach((t) => pc.addTrack(t, stream));

      // 4) Data channel for session control + transcript events.
      const dc = pc.createDataChannel("oai-events");
      dcRef.current = dc;

      const configure = () => {
        if (configuredRef.current) return;
        configuredRef.current = true;
        // Voice is locked after the first audio output, so set it now, before any
        // response. reasoning.effort nests under session, per the lifecycle docs.
        send({
          type: "session.update",
          session: {
            type: "realtime",
            model: agent.model,
            output_modalities: ["audio"],
            instructions: agent.instructions,
            audio: {
              input: {
                turn_detection: agent.turnDetection,
                transcription: agent.transcription,
              },
              output: { voice: agent.voice },
            },
            reasoning: { effort: agent.reasoningEffort },
          },
        });
      };

      const greet = () => {
        if (greetedRef.current) return;
        greetedRef.current = true;
        setCallState("listening");
        setCaption("listening…");
        send({
          type: "conversation.item.create",
          item: {
            type: "message",
            role: "user",
            content: [{ type: "input_text", text: agent.firstMessage }],
          },
        });
        send({ type: "response.create" });
      };

      dc.onopen = () => {
        if (endedRef.current) return;
        configure();
      };

      dc.onmessage = (event) => {
        if (endedRef.current) return;
        let msg: OpenaiEvent;
        try {
          msg = JSON.parse(typeof event.data === "string" ? event.data : "") as OpenaiEvent;
        } catch {
          return;
        }
        switch (msg.type) {
          case "session.created":
            configure();
            break;
          case "session.updated":
            greet();
            break;
          case "response.created":
            if (stateRef.current !== "interrupted") setCallState("speaking");
            break;
          case "response.output_audio_transcript.delta":
            if (msg.delta) {
              if (stateRef.current !== "interrupted") setCallState("speaking");
              pushAgentDelta(msg.delta);
            }
            break;
          case "response.done":
            finalizeAgent();
            if (stateRef.current === "speaking") setCallState("listening");
            break;
          case "input_audio_buffer.speech_started":
            // Server VAD detected the user — server truncates the model audio for
            // us on WebRTC; reflect the barge-in in the UI.
            finalizeAgent();
            setCallState("interrupted");
            if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
            interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
            break;
          case "input_audio_buffer.speech_stopped":
          case "input_audio_buffer.committed":
            if (stateRef.current === "interrupted") setCallState("listening");
            break;
          case "conversation.item.input_audio_transcription.delta":
            if (msg.delta) pushUserDelta(msg.delta);
            break;
          case "conversation.item.input_audio_transcription.completed":
            finalizeUser(msg.transcript ?? "");
            break;
          case "error":
            setCaption(`— ${msg.error?.message ?? "OpenAI error"} —`);
            break;
          default:
            break;
        }
      };

      // 5) Mint the ephemeral key, then exchange SDP with OpenAI.
      let token: string | null = null;
      try {
        const res = await fetch("/api/openai/token", { method: "POST" });
        const data = await res.json();
        if (!res.ok) {
          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
          return;
        }
        token = extractToken(data);
      } catch {
        fail("— could not reach token endpoint —");
        return;
      }
      if (!token) {
        fail("— no OpenAI token returned —");
        return;
      }
      if (endedRef.current) return;

      try {
        const offer = await pc.createOffer();
        await pc.setLocalDescription(offer);
        const sdpRes = await fetch(CALLS_URL, {
          method: "POST",
          body: offer.sdp,
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/sdp",
          },
        });
        if (!sdpRes.ok) {
          fail(`— OpenAI call setup failed (${sdpRes.status}) —`);
          return;
        }
        const answer: RTCSessionDescriptionInit = { type: "answer", sdp: await sdpRes.text() };
        if (endedRef.current) return;
        await pc.setRemoteDescription(answer);
      } catch {
        fail("— could not establish WebRTC session —");
        return;
      }
    })();
  }, [send, teardown]);

  const stop = useCallback(() => {
    endedRef.current = true;
    teardown();
    setCallState("ended");
    setCaption("— call ended —");
  }, [teardown]);

  const interrupt = useCallback(() => {
    if (stateRef.current !== "speaking") return;
    // Cancel the in-progress response and clear any unplayed server audio.
    send({ type: "response.cancel" });
    send({ type: "output_audio_buffer.clear" });
    setCallState("interrupted");
    if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
    interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
  }, [send]);

  const setMuted = useCallback((muted: boolean) => {
    mutedRef.current = muted;
    streamRef.current?.getAudioTracks().forEach((t) => (t.enabled = !muted));
  }, []);

  const getInputVolume = useCallback(() => {
    if (mutedRef.current) return 0;
    return analyserLevel(inAnalyserRef.current, inBufRef.current);
  }, []);
  const getOutputVolume = useCallback(
    () => analyserLevel(outAnalyserRef.current, outBufRef.current),
    [],
  );

  // Hang up + reset if the provider is switched away from OpenAI mid-session.
  useEffect(() => {
    if (active) return;
    if (stateRef.current !== "idle") {
      endedRef.current = true;
      teardown();
      setCallState("idle");
      setTurns([]);
      setCaption("press CALL to begin");
    }
  }, [active, teardown]);

  // Cleanup on unmount.
  useEffect(() => () => teardown(), [teardown]);

  return {
    callState,
    turns,
    caption,
    start,
    stop,
    interrupt,
    setMuted,
    getInputVolume,
    getOutputVolume,
  };
}

