async () => {
  // wait ~6s for the greeting to complete and any follow-up
  await new Promise((r) => setTimeout(r, 6000));
  const ev = window.__oaiEvents || [];
  const counts = {};
  for (const t of ev) counts[t] = (counts[t] || 0) + 1;
