input.initScript:
window.__oai = { sent: [], events: [], errors: [] };
const origCreate = RTCPeerConnection.prototype.createDataChannel;
RTCPeerConnection.prototype.createDataChannel = function (...args) {
  const dc = origCreate.apply(this, args);
  if (args[0] === "oai-events") {
    const origSend = dc.send.bind(dc);
    dc.send = (data) => {
      try {
        window.__oai.sent.push(JSON.parse(data));
      } catch {}
      return origSend(data);
    };
    dc.addEventListener("message", (e) => {
      try {
        const m = JSON.parse(e.data);
        window.__oai.events.push(m.type);
        if (m.type === "error") window.__oai.errors.push(m);
      } catch {}
    });
  }
  return dc;
};

